        (x.sigils.length ? '<div class="bld-sig">' + x.sigils.map(function (g) { return itemCell(g); }).join('') + '</div>' : '') + '</td><td>' + statCell(x.stat) + '</td></tr>';
    }).join('');
  }).join('') + '</tbody></table>');
}

if (v.extras.length) {
